    }

    /**
     * Adds a JOIN clause to the query using the ComInterna relation
     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return TipoComInternaQuery The current query, for fluid interface
     */
    public function joinComInterna($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('ComInterna');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'ComInterna');
        }

        return $this;
    }

    /**
     * Use the ComInterna relation ComInterna object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   ComInternaQuery A secondary query class using the current class as primary query
     */
    public function useComInternaQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinComInterna($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'ComInterna', 'ComInternaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   TipoComInterna $tipoComInterna Object to remove from the list of results
     *
     * @return TipoComInternaQuery The current query, for fluid interface
     */
    public function prune($tipoComInterna = null)
    {
        if ($tipoComInterna) {
            $this->addUsingAlias(TipoComInternaPeer::TIPOCOMINTERNA_ID, $tipoComInterna->getTipocominternaId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

